/**
 * Admin 管理接口控制器 (M7+)
 *
 * 对应 PHP app/controller/admin/v1/ 下的:
 *   - product/StoreProduct.php (商品管理)
 *   - order/StoreOrder.php (订单管理)
 *   - user/User.php (用户管理)
 *   - system/config/SystemConfig.php (系统配置)
 *
 * 所有接口需要 admin token (adminAuthMiddleware)
 */
import type { Context } from "hono";
import * as AdminProductCategories from './AdminProductCategoryController';
import * as AdminConfigClass from './AdminConfigClassController';
import { jsonOk, jsonFail } from "@/utils/json";
import type { AppVariables, Env } from "@/env";
import { AdminPermissionService } from "@/services/admin/AdminPermissionService";
import { AdminAuthorityWriteService, type AdminAuthorityActor } from "@/services/admin/AdminAuthorityWriteService";
import { ValidateException } from "@/utils/errors";
