  bgTabVal?: 0 | 1 | 2;
}

export type AdminDiseSaveInput =
  | ({ mode: "update"; id: number } & AdminDiseEditableFields)
  | ({
      mode: "create";
      createKind: "diy_page";
      name: string;
      title?: string;
      value: string;
      content?: string;
      isShow?: 0;
      isBgColor?: 0 | 1;
