  let writeOk: boolean | string = false;
  let readOk: boolean | string = false;
  let readVal = null;
  try {
    writeOk = await setTokenBucket(testKey, testBucket, c.env);
  } catch (e) {
    writeOk = `error: ${e instanceof Error ? e.message : String(e)}`;
  }
