import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {resolve} from 'node:path';
import {describe,expect,it} from 'vitest';
import {buildAdminFrontendApiAuditReport} from '../scripts/admin-frontend-api-audit';
import {expressSourceBinding as proof,reverseExpressSource,readExpressPredecessor,readPlatformMenuPredecessor,platformMenuSourceBinding,reversePlatformMenuSource,buildExpressPredecessorApiAuditReport} from './helpers/expressSourceBinding';
import {EXPRESS_FIELDS} from '../../view/common/expressAuthor';
const root=resolve(import.meta.dirname,'../..'),read=(f:string)=>readFileSync(resolve(root,f),'utf8'),sha=(v:string|Uint8Array)=>createHash('sha256').update(v).digest('hex');
describe('complete express PHP chain, exact additive producer evidence and preserved predecessors',()=>{
 for(const row of proof.sources){
  it(`pins whole actual producer and exact predecessor ${row.file}`,()=>{const actual=read(row.file);expect(sha(actual)).toBe(row.after_sha256);expect(sha(reverseExpressSource(row.file,actual))).toBe(row.before_sha256);expect(sha(readExpressPredecessor(resolve(root,row.file)))).toBe(row.before_sha256);});
  it(`rejects source truncation, append, duplication and forged mappings ${row.file}`,()=>{const actual=read(row.file);for(const bad of [actual.slice(1),actual+'\n// unreviewed\n',actual+actual])expect(()=>reverseExpressSource(row.file,bad)).toThrow();for(const key of ['before_sha256','after_sha256'] as const){const forged=structuredClone(proof);forged.sources.find(r=>r.file===row.file)![key]='0'.repeat(64);expect(()=>reverseExpressSource(row.file,actual,forged)).toThrow();}const forged=structuredClone(proof);forged.sources.find(r=>r.file===row.file)!.edits[0]!.after_line=2;expect(()=>reverseExpressSource(row.file,actual,forged)).toThrow();});
  if(row.file.startsWith('workers-ts/test/'))it(`preserves every predecessor assertion and negative fixture ${row.file}`,()=>{const strip=(s:string)=>s.replace(/^import[\s\S]*?;\n/gmu,'');expect(strip(row.edits[0]!.after_source)).toBe(strip(row.edits[0]!.before_source));});
